fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    let tol = tol as i16;
    let diff = (a as i16) - (b as i16);
    diff > -tol && diff < tol
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Length equality and positive length assumed by problem.
    // Iterate and check element-wise closeness.
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| is_close_i8(x, y, tol))
     .collect()
}